-- Table: Banks (Financial Institutions & Gateways)
CREATE TABLE [dbo].[Banks] (
    [BankId] INT IDENTITY(1,1) NOT NULL,
    [BankCode] VARCHAR(20) NOT NULL,
    [BankName] NVARCHAR(100) NOT NULL,
    [RoutingNumber] VARCHAR(30) NOT NULL,
    [Country] NVARCHAR(50) NOT NULL DEFAULT ('United States'),
    [SupportedCurrencies] VARCHAR(50) NOT NULL DEFAULT ('USD,EUR,GBP'),
    [AvgLatencyMs] INT NOT NULL DEFAULT (120),
    [FeeRatePct] DECIMAL(5,4) NOT NULL DEFAULT (0.0150),
    [IsActive] BIT NOT NULL DEFAULT (1),
    [CreatedAt] DATETIME2(0) NOT NULL DEFAULT (SYSUTCDATETIME()),
    CONSTRAINT [PK_Banks] PRIMARY KEY CLUSTERED ([BankId] ASC),
    CONSTRAINT [UQ_Banks_BankCode] UNIQUE NONCLUSTERED ([BankCode] ASC)
);
GO

-- Table: Employees (Sales Representatives, Account Executives, Support Staff)
CREATE TABLE [dbo].[Employees] (
    [EmployeeId] INT IDENTITY(1,1) NOT NULL,
