    [Email] NVARCHAR(150) NOT NULL,              -- PII
    [JobTitle] NVARCHAR(80) NOT NULL,
    [Department] NVARCHAR(50) NOT NULL,
    [Region] NVARCHAR(50) NOT NULL,
    [Salary] DECIMAL(18,2) NOT NULL,             -- Sensitive PII
    [CommissionRate] DECIMAL(5,4) NOT NULL DEFAULT (0.0500),
    [AnnualQuota] DECIMAL(18,2) NOT NULL DEFAULT (500000.00),
    [HireDate] DATE NOT NULL,
    [IsActive] BIT NOT NULL DEFAULT (1),
    CONSTRAINT [PK_Employees] PRIMARY KEY CLUSTERED ([EmployeeId] ASC),
    CONSTRAINT [UQ_Employees_EmployeeCode] UNIQUE NONCLUSTERED ([EmployeeCode] ASC),
    CONSTRAINT [UQ_Employees_Email] UNIQUE NONCLUSTERED ([Email] ASC)
);
GO

