-- View 1: Daily Revenue Summary (For time series, line charts, and forecasting)
CREATE VIEW [dbo].[vw_DailyRevenueSummary] AS
SELECT 
    CAST(OrderDate AS DATE) AS OrderDate,
    COUNT(DISTINCT OrderId) AS TotalOrders,
    COUNT(DISTINCT CustomerId) AS UniqueCustomers,
    SUM(SubTotal) AS GrossSales,
    SUM(DiscountAmount) AS TotalDiscounts,
    SUM(TaxAmount) AS TotalTaxes,
    SUM(TotalAmount) AS NetRevenue,
    ROUND(AVG(TotalAmount), 2) AS AverageOrderValue
FROM [dbo].[Orders]
WHERE OrderStatus IN ('Completed', 'Shipped')
GROUP BY CAST(OrderDate AS DATE);
GO

-- View 2: Executive KPI Snapshot (For Phase 5 & Phase D Morning Executive Brief)
CREATE VIEW [dbo].[vw_ExecutiveKpiSnapshot] AS
SELECT
    (SELECT COUNT(*) FROM [dbo].[Customers] WHERE CustomerStatus = 'Active') AS ActiveCustomerCount,
    (SELECT COUNT(*) FROM [dbo].[Orders] WHERE OrderStatus IN ('Completed', 'Shipped')) AS TotalCompletedOrders,
    (SELECT ISNULL(SUM(TotalAmount), 0) FROM [dbo].[Orders] WHERE OrderStatus IN ('Completed', 'Shipped')) AS TotalLifetimeRevenue,
    (SELECT ISNULL(ROUND(AVG(TotalAmount), 2), 0) FROM [dbo].[Orders] WHERE OrderStatus IN ('Completed', 'Shipped')) AS AverageOrderValue,
    (SELECT ISNULL(SUM(MonthlyRecurringRevenue), 0) FROM [dbo].[Subscriptions] WHERE SubscriptionStatus = 'Active') AS CurrentActiveMRR,
    (SELECT ROUND(CAST(COUNT(CASE WHEN PaymentStatus = 'Completed' THEN 1 END) AS FLOAT) * 100.0 / NULLIF(COUNT(*), 0), 2) FROM [dbo].[Payments]) AS OverallPaymentSuccessRatePct;
GO

-- View 3: Bank Transaction Performance (For Bank comparison & Anomaly detection)
CREATE VIEW [dbo].[vw_BankTransactionPerformance] AS
SELECT
    b.BankId,
    b.BankCode,
    b.BankName,
    COUNT(p.PaymentId) AS TotalTransactions,
    SUM(CASE WHEN p.PaymentStatus = 'Completed' THEN 1 ELSE 0 END) AS SuccessfulTransactions,
    SUM(CASE WHEN p.PaymentStatus = 'Failed' THEN 1 ELSE 0 END) AS FailedTransactions,
    ROUND(CAST(SUM(CASE WHEN p.PaymentStatus = 'Completed' THEN 1 ELSE 0 END) AS FLOAT) * 100.0 / NULLIF(COUNT(p.PaymentId), 0), 2) AS SuccessRatePct,
    ISNULL(SUM(CASE WHEN p.PaymentStatus = 'Completed' THEN p.Amount ELSE 0 END), 0) AS TotalProcessedVolume,
    ISNULL(SUM(p.ProcessingFee), 0) AS TotalProcessingFees,
    ROUND(AVG(CAST(b.AvgLatencyMs AS FLOAT)), 0) AS AverageLatencyMs
FROM [dbo].[Banks] b
LEFT JOIN [dbo].[Payments] p ON b.BankId = p.BankId
GROUP BY b.BankId, b.BankCode, b.BankName;
GO

-- View 4: Customer Lifetime Value & Churn Risk (For Phase H & Retention Analysis)
CREATE VIEW [dbo].[vw_CustomerLifetimeValue] AS
SELECT
    c.CustomerId,
    c.CustomerCode,
    c.CompanyName,
    c.CustomerSegment,
    c.Region,
    c.CustomerStatus,
    c.CreatedAt AS CustomerSince,
    COUNT(DISTINCT o.OrderId) AS LifetimeOrderCount,
    ISNULL(SUM(o.TotalAmount), 0) AS LifetimeTotalSpend,
    ROUND(ISNULL(AVG(o.TotalAmount), 0), 2) AS AverageOrderSize,
    MAX(o.OrderDate) AS MostRecentOrderDate,
    DATEDIFF(DAY, MAX(o.OrderDate), '2026-10-01') AS DaysSinceLastOrder
FROM [dbo].[Customers] c
LEFT JOIN [dbo].[Orders] o ON c.CustomerId = o.CustomerId AND o.OrderStatus IN ('Completed', 'Shipped')
GROUP BY c.CustomerId, c.CustomerCode, c.CompanyName, c.CustomerSegment, c.Region, c.CustomerStatus, c.CreatedAt;
GO

-- View 5: Inventory Stock Alerts (For Phase H Restocking Recommendations)
CREATE VIEW [dbo].[vw_InventoryStockAlerts] AS
SELECT
    p.ProductId,
    p.ProductSku,
    p.ProductName,
    c.CategoryName,
    i.WarehouseLocation,
    i.QuantityOnHand,
    i.QuantityReserved,
    (i.QuantityOnHand - i.QuantityReserved) AS QuantityAvailable,
    i.ReorderLevel,
    i.ReorderQuantity,
    CASE 
        WHEN i.QuantityOnHand = 0 THEN 'OUT_OF_STOCK'
        WHEN i.QuantityOnHand <= (i.ReorderLevel * 0.5) THEN 'CRITICAL_LOW'
        WHEN i.QuantityOnHand <= i.ReorderLevel THEN 'REORDER_NEEDED'
        ELSE 'ADEQUATE'
    END AS StockStatus,
    (i.ReorderLevel - i.QuantityOnHand + i.ReorderQuantity) AS SuggestedOrderQuantity
FROM [dbo].[Inventory] i
JOIN [dbo].[Products] p ON i.ProductId = p.ProductId
JOIN [dbo].[Categories] c ON p.CategoryId = c.CategoryId
WHERE i.QuantityOnHand <= i.ReorderLevel;
GO

-- View 6: Electronic Banking System Transactions (For EBS View Discovery)
CREATE VIEW [dbo].[vw_ElectronicBankingSystem_Transactions] AS
SELECT
    t.TransactionId,
    t.ExternalTraceNumber,
    t.SourceBankCode,
    t.DestinationBankCode,
    t.ChannelType,
    t.TransactionType,
    t.Amount,
    t.InterchangeFee,
    t.ProcessingStatus,
    t.ErrorCode,
    t.TransactionTimestamp,
    CAST(t.TransactionTimestamp AS DATE) AS TransactionDate,
    DATEPART(HOUR, t.TransactionTimestamp) AS TransactionHour
FROM [dbo].[EbsTransactions] t;
GO

