-- Procedure 1: Monthly Financial Summary Report
CREATE PROCEDURE [dbo].[sp_GetMonthlyFinancialSummary]
    @CalendarYear INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    IF @CalendarYear IS NULL SET @CalendarYear = 2026;

    SELECT
        YEAR(o.OrderDate) AS [Year],
        MONTH(o.OrderDate) AS [MonthNumber],
        DATENAME(MONTH, o.OrderDate) AS [MonthName],
        COUNT(DISTINCT o.OrderId) AS TotalOrders,
        COUNT(DISTINCT o.CustomerId) AS ActiveCustomers,
        SUM(o.SubTotal) AS GrossSales,
        SUM(o.DiscountAmount) AS TotalDiscounts,
        SUM(o.TotalAmount) AS NetRevenue,
        ROUND(AVG(o.TotalAmount), 2) AS AverageOrderValue
    FROM [dbo].[Orders] o
    WHERE YEAR(o.OrderDate) = @CalendarYear
      AND o.OrderStatus IN ('Completed', 'Shipped')
    GROUP BY YEAR(o.OrderDate), MONTH(o.OrderDate), DATENAME(MONTH, o.OrderDate)
    ORDER BY [Year], [MonthNumber];
END;
GO

-- Procedure 2: Detect Transaction Outages & Spikes
CREATE PROCEDURE [dbo].[sp_DetectTransactionAnomalies]
    @ThresholdFailureRatePct DECIMAL(5,2) = 10.0,
    @MinTransactionVolume INT = 5
AS
BEGIN
    SET NOCOUNT ON;

    WITH DailyBankStats AS (
        SELECT
            CAST(p.PaymentDate AS DATE) AS TransactionDate,
            b.BankCode,
            b.BankName,
            COUNT(p.PaymentId) AS TotalVolume,
            SUM(CASE WHEN p.PaymentStatus = 'Failed' THEN 1 ELSE 0 END) AS FailedCount,
            ROUND(CAST(SUM(CASE WHEN p.PaymentStatus = 'Failed' THEN 1 ELSE 0 END) AS FLOAT) * 100.0 / COUNT(p.PaymentId), 2) AS FailureRatePct,
            SUM(CASE WHEN p.PaymentStatus = 'Failed' THEN p.Amount ELSE 0 END) AS ImpactedFailedAmount
        FROM [dbo].[Payments] p
        JOIN [dbo].[Banks] b ON p.BankId = b.BankId
        GROUP BY CAST(p.PaymentDate AS DATE), b.BankCode, b.BankName
    )
    SELECT
        TransactionDate,
        BankCode,
        BankName,
        TotalVolume,
        FailedCount,
        FailureRatePct,
        ImpactedFailedAmount,
        'High Failure Rate Anomaly' AS AnomalyType,
        CASE 
            WHEN FailureRatePct >= 30.0 THEN 'CRITICAL - Outage Likely'
            WHEN FailureRatePct >= 15.0 THEN 'HIGH - Degraded Service'
            ELSE 'MODERATE - Elevated Failures'
        END AS Severity
    FROM DailyBankStats
    WHERE FailureRatePct >= @ThresholdFailureRatePct
      AND TotalVolume >= @MinTransactionVolume
    ORDER BY FailureRatePct DESC, ImpactedFailedAmount DESC;
END;
GO

PRINT '>>> Stored procedures created successfully.';
GO

