INSERT INTO [dbo].[Categories] ([CategoryId], [CategoryCode], [CategoryName], [Description])
VALUES
  (1, 'CAT-CLOUD', 'Cloud Infrastructure & Compute', 'Scalable cloud computing clusters, virtual instances, and memory fabrics.'),
  (2, 'CAT-AI-ML', 'AI & Machine Learning Platforms', 'Agentic AI runtimes, vector embeddings, fine-tuning infrastructure, and LLM gateways.'),
  (3, 'CAT-SECURITY', 'Enterprise Cybersecurity & Access', 'Zero trust security, identity management, encrypted transit tunnels, and compliance scanners.'),
  (4, 'CAT-ANALYTICS', 'Data Analytics & Business Intelligence', 'Real-time OLAP streaming, semantic layers, dashboard builders, and automated reporting.'),
  (5, 'CAT-DEVTOOLS', 'Developer Tools & Workspace Platforms', 'Continuous integration tools, API gateways, automated testing, and developer environments.'),
  (6, 'CAT-CONSULTING', 'Professional Services & Architectural Advisory', 'Onboarding packages, dedicated solution architecture, and 24/7 mission-critical SLA.');
